const heroVideo = document.getElementById('hero-video');
const standardVideo = document.getElementById('standard-video');
const canvas = document.getElementById('flux-canvas');
const gif = document.getElementById('pulsar-gif');
const gifBox = document.getElementById('simulation-gif-box');

if (!heroVideo || !standardVideo || !canvas || !gif || !gifBox) return false;

const styleTag = document.getElementById('ai4a11y-flash-guard-styles');
if (!styleTag) return false;

if (heroVideo.hasAttribute('autoplay')) return false;
